"""Render V3 status from preregistered artefacts."""
import json
from pathlib import Path


def pct(value):
    return f'{value * 100:.2f}%'


def metrics(result):
    item = result['factory_month']
    return f"recall {pct(item['recall'])}, FPR {pct(item['fpr'])}, precision {pct(item['precision'])}"


b = json.loads(Path('reports/v3_b_results.json').read_text())
c = json.loads(Path('reports/v3_c_results.json').read_text())
lines = [
    '<!-- Generated by scripts/render_preregistration_scorecard.py. -->',
    '# Preregistration scorecard', '',
    'V3 was preregistered in `docs/preregistration_v3.md` before generation. V3-A is calibration; V3-B and V3-C are held-out reports. V2 artefacts remain DEV history only.', '',
    '| Criterion | Status | Measured value or evidence |', '|---|---|---|',
    f'| V3-B factory-month result | HELDOUT | {metrics(b)}. |',
    f'| V3-C confirmation result | HELDOUT | {metrics(c)}. |',
    f'| Frozen calibration | DEV | threshold {b["protocol"]["threshold"]:.3f}; K={b["factory_queue"]["k"]}; selected on V3-A only. |',
    '| Label isolation | VERIFIED | Offline tests block detector and officer-interface outcome-label references. |',
    '| Ranking matches evaluation | VERIFIED | Source-level rank-order test passes. |',
    '| Single-signal clear requires verified metadata | VERIFIED | SQL contract test covers rejected and verified records. |',
    '| Wrong-clear outcome | HELDOUT | V3 disposition reports record zero active-cheat wrong clears; this is synthetic metadata verification only. |',
    '| Regenerated realistic-prevalence population | NOT-IMPLEMENTED | No new regenerated low-prevalence population. |',
    '| Fair repeated database and dataframe benchmark | NOT-IMPLEMENTED | Existing comparison predates the current detector. |',
    '| Large mixed-workload concurrency | NOT-IMPLEMENTED | Existing run is limited local evidence. |',
    '| Advanced database extension | NOT-IMPLEMENTED | No successful dated transcript and test. |',
    '| Clean-machine from-scratch reproduction | NOT-IMPLEMENTED | Fresh source/venv offline smoke passed; separate-machine database installation remains unverified. |',
    '| Full-scale current-detector benchmark | NOT-IMPLEMENTED | Existing full-scale workload predates the current detector. |',
]
Path('docs/archive/PREREGISTRATION_SCORECARD.md').write_text('\n'.join(lines) + '\n')
